class Solution {
    string text;
    vector<vector<int>> memo;
    int encoded(int count){
        return count==1?1:count<10?2:count<100?3:4;
    }
    int dfs(int index,int k){
        if((int)text.size()-index<=k)return 0;
        if(k<0)return 1000000;
        int& cached=memo[index][k];
        if(cached!=-1)return cached;
        int answer=dfs(index+1,k-1),same=0,removed=0;
        for(int end=index;end<(int)text.size();++end){
            text[end]==text[index]?++same:++removed;
            if(removed>k)break;
            answer=min(answer,encoded(same)+dfs(end+1,k-removed));
        }
        return cached=answer;
    }
    public:int getLengthOfOptimalCompression(string s,int k){
        text=s;
        memo.assign(s.size(),vector<int>(k+1,-1));
        return dfs(0,k);
    }
};
